// Type stubs for Docusaurus path aliases (e.g. @theme/Layout, @docusaurus/Link).
// Docusaurus wires these up at build time; these ambient declarations just keep
// the type-checker happy for editor/`pnpm typecheck` purposes.
declare module '@theme/*'
declare module '@theme-original/*'
declare module '@docusaurus/*'
declare module '@site/*'
declare module '@generated/*'
